pub(crate) mod official_minimap {
    /// The mod's id (its settings folder), name and version.
    pub const ID: &str = "minimap";
    pub const NAME: &str = "Minimap";
    pub const VERSION: &str = "2.0.0";
    pub const DESCRIPTION: &str = "A map of the terrain around you in a corner, in map colours, square or round, north up or turning with you. Horizon's own.";
    /// The corners, as the settings files name them and the page labels them.
    pub const CORNERS: [(&str, &str); 4] = [
        ("top_left", "Top left"),
        ("top_right", "Top right"),
        ("bottom_left", "Bottom left"),
        ("bottom_right", "Bottom right"),
    ];
    /// Sides in GUI pixels, and blocks per map pixel.
    pub const SIZES: [(u8, &str); 3] = [(64, "Small"), (96, "Medium"), (128, "Large")];
    pub const ZOOMS: [f32; 4] = [0.5, 1.0, 2.0, 4.0];
    /// The settings, as the WebAssembly Minimap kept them.
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct Settings {
        /// Indices in `CORNERS`, `SIZES` and `ZOOMS`.
        pub corner: usize,
        pub size: usize,
        pub round: bool,
        pub zoom: usize,
        pub rotate: bool,
    }
    impl Settings {
        /// From the stored values; the extra's defaults (top right, medium,
        /// square, 1 block per pixel, north up) for the ones missing.
        pub fn read(get: impl Fn(&str) -> Option<String>) -> Self {
            let get = |key: &str| get(key).map(|v| v.trim().to_owned());
            let find = |key: &str, values: &[String], default: usize| {
                get(key)
                    .and_then(|v| values.iter().position(|s| *s == v))
                    .unwrap_or(default)
            };
            let corners: Vec<String> = CORNERS.iter().map(|c| c.0.to_owned()).collect();
            let sizes: Vec<String> = SIZES.iter().map(|s| s.0.to_string()).collect();
            let zooms: Vec<String> = ZOOMS.iter().map(f32::to_string).collect();
            Self {
                corner: find("corner", &corners, 1),
                size: find("size", &sizes, 1),
                round: get("shape").as_deref() == Some("round"),
                zoom: find("zoom", &zooms, 1),
                rotate: get("rotate").as_deref() == Some("true"),
            }
        }
        pub fn labels(&self) -> Vec<String> {
            let n = ZOOMS[self.zoom];
            let blocks = if n < 1.0 {
                "½ block".to_owned()
            } else if n == 1.0 {
                "1 block".to_owned()
            } else {
                format!("{n} blocks")
            };
            vec![
                format!("Corner: {}", CORNERS[self.corner].1), format!("Size: {}",
                SIZES[self.size].1), format!("Shape: {}", if self.round { "Round" } else
                { "Square" }), format!("Zoom: {blocks} per pixel"),
                format!("Turn with the player: {}", if self.rotate { "ON" } else { "OFF"
                }),
            ]
        }
        pub fn click(&mut self, i: usize) {
            let next = |i: usize, n: usize| (i + 1) % n;
            match i {
                0 => self.corner = next(self.corner, CORNERS.len()),
                1 => self.size = next(self.size, SIZES.len()),
                2 => self.round = !self.round,
                3 => self.zoom = next(self.zoom, ZOOMS.len()),
                4 => self.rotate = !self.rotate,
                _ => {}
            }
        }
        pub fn stored(&self) -> [(&'static str, String); 5] {
            [
                ("corner", CORNERS[self.corner].0.to_owned()),
                ("size", SIZES[self.size].0.to_string()),
                ("shape", if self.round { "round" } else { "square" }.to_owned()),
                ("zoom", ZOOMS[self.zoom].to_string()),
                ("rotate", if self.rotate { "true" } else { "false" }.to_owned()),
            ]
        }
        /// What Horizon's minimap draws: (side, blocks per pixel).
        pub fn view(&self) -> (f32, f32) {
            (f32::from(SIZES[self.size].0), ZOOMS[self.zoom])
        }
    }
    thread_local! {
        #[doc = " The settings, read once from the files, then kept."] static SETTINGS :
        std::cell::Cell < Option < Settings >> = const { std::cell::Cell::new(None) };
    }
    /// The settings, read once through `get` (one file per key).
    pub fn settings(get: impl Fn(&str) -> Option<String>) -> Settings {
        SETTINGS
            .with(|s| {
                let found = s.get().unwrap_or_else(|| Settings::read(get));
                s.set(Some(found));
                found
            })
    }
    /// Replaces the settings (the settings page changed them).
    pub fn set_settings(settings: Settings) {
        SETTINGS.with(|s| s.set(Some(settings)));
    }
    #[cfg(test)]
    mod tests {
        use super::*;
        #[test]
        fn reads_and_writes_the_webassembly_mods_settings() {
            let none = |_: &str| None;
            let s = Settings::read(none);
            assert_eq!(
                (s.corner, s.size, s.round, s.zoom, s.rotate), (1, 1, false, 1, false)
            );
            let files = [
                ("corner", "bottom_left"),
                ("size", "128\n"),
                ("shape", "round"),
                ("zoom", "0.5"),
                ("rotate", "true"),
            ];
            let get = |k: &str| files.iter().find(|f| f.0 == k).map(|f| f.1.to_owned());
            let mut s = Settings::read(get);
            assert_eq!(s.view(), (128.0, 0.5));
            assert_eq!(
                s.labels(), ["Corner: Bottom left", "Size: Large", "Shape: Round",
                "Zoom: ½ block per pixel", "Turn with the player: ON"]
            );
            s.click(3);
            s.click(3);
            assert_eq!(s.stored() [3], ("zoom", "2".to_owned()));
            let round = s.stored();
            let back = Settings::read(|k: &str| {
                round.iter().find(|f| f.0 == k).map(|f| f.1.clone())
            });
            assert_eq!(back, s);
        }
    }
}
pub(crate) mod official_zoom {
    use std::cell::RefCell;
    /// The mod's id: its settings folder and its key's line.
    pub const ID: &str = "zoom";
    pub const VERSION: &str = "2.0.0";
    pub const DESCRIPTION: &str = "Hold a key to zoom in; the mouse wheel changes the zoom while you hold it. Horizon's own.";
    /// The key's name, and its default.
    pub const KEY: &str = "zoom";
    pub const DEFAULT_KEY: &str = "key.keyboard.z";
    /// The zooms the starting zoom cycles through, and the wheel's limits.
    pub const LEVELS: [u8; 6] = [2, 3, 4, 6, 8, 10];
    const MIN: f32 = 1.25;
    const MAX: f32 = 10.0;
    /// Each wheel step multiplies the zoom by this.
    const STEP: f32 = 1.25;
    /// The settings, as the WebAssembly Zoom kept them.
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct Settings {
        /// The zoom the key starts at, one of `LEVELS`.
        pub level: u8,
        /// Ease in and out like the spyglass.
        pub smooth: bool,
        /// Turn slower the more you zoom in.
        pub sensitivity: bool,
    }
    impl Settings {
        /// From the stored values (`get` reads one key's file); the extra's
        /// defaults (4x, smooth, slower turning) for the ones missing.
        pub fn read(get: impl Fn(&str) -> Option<String>) -> Self {
            let level = get("level")
                .and_then(|v| v.trim().parse::<u8>().ok())
                .map_or(4, |v| v.clamp(2, MAX as u8));
            let flag = |key: &str| get(key).is_none_or(|v| v.trim() != "false");
            Self {
                level,
                smooth: flag("smooth"),
                sensitivity: flag("sensitivity"),
            }
        }
        /// The settings page's buttons, as the WebAssembly Zoom labelled them.
        pub fn labels(&self) -> Vec<String> {
            let on = |b: bool| if b { "ON" } else { "OFF" };
            vec![
                format!("Starting zoom: {}x", self.level), format!("Smooth zoom: {}",
                on(self.smooth)), format!("Slower turning: {}", on(self.sensitivity)),
            ]
        }
        /// A click on button `i` of `labels`.
        pub fn click(&mut self, i: usize) {
            match i {
                0 => {
                    let at = LEVELS.iter().position(|&l| l == self.level).unwrap_or(0);
                    self.level = LEVELS[(at + 1) % LEVELS.len()];
                }
                1 => self.smooth = !self.smooth,
                2 => self.sensitivity = !self.sensitivity,
                _ => {}
            }
        }
        /// What to store, key by key.
        pub fn stored(&self) -> [(&'static str, String); 3] {
            let flag = |b: bool| if b { "true" } else { "false" }.to_owned();
            [
                ("level", self.level.to_string()),
                ("smooth", flag(self.smooth)),
                ("sensitivity", flag(self.sensitivity)),
            ]
        }
    }
    #[derive(Default)]
    struct State {
        /// Read on the first key press, then kept.
        settings: Option<Settings>,
        /// The zoom while the key is held; None when it is up.
        held: Option<f32>,
    }
    thread_local! {
        static STATE : RefCell < State > = RefCell::new(State::default());
    }
    /// The settings, read once through `get`.
    pub fn settings(get: impl Fn(&str) -> Option<String>) -> Settings {
        STATE.with_borrow_mut(|s| *s.settings.get_or_insert_with(|| Settings::read(get)))
    }
    /// Replaces the settings (the settings page changed them).
    pub fn set_settings(settings: Settings) {
        STATE.with_borrow_mut(|s| s.settings = Some(settings));
    }
    /// The zoom key went down (only while playing) or up.
    pub fn key(playing: bool, pressed: bool, get: impl Fn(&str) -> Option<String>) {
        if pressed && !playing {
            return;
        }
        let level = settings(get).level;
        STATE
            .with_borrow_mut(|s| {
                s.held = pressed.then(|| f32::from(level).clamp(MIN, MAX));
            });
    }
    /// Wheel steps: true when the key is held and they zoom.
    pub fn wheel(steps: f32) -> bool {
        STATE
            .with_borrow_mut(|s| {
                let Some(z) = &mut s.held else {
                    return false;
                };
                *z = (*z * STEP.powf(steps)).clamp(MIN, MAX);
                true
            })
    }
    /// The zoom in effect: (factor, smooth, turning scale), none when the key
    /// is up.
    pub fn view() -> Option<(f32, bool, f32)> {
        STATE
            .with_borrow(|s| {
                let factor = s.held?;
                let settings = s.settings?;
                let turn = if settings.sensitivity { 1.0 / factor } else { 1.0 };
                Some((factor, settings.smooth, turn))
            })
    }
    #[cfg(test)]
    mod tests {
        use super::*;
        fn stored<'a>(
            pairs: &'a [(&'a str, &'a str)],
        ) -> impl Fn(&str) -> Option<String> + 'a {
            |key| pairs.iter().find(|p| p.0 == key).map(|p| p.1.to_owned())
        }
        #[test]
        fn reads_the_webassembly_mods_settings() {
            assert_eq!(
                Settings::read(stored(& [])), Settings { level : 4, smooth : true,
                sensitivity : true }
            );
            let s = Settings::read(
                stored(&[("level", "8\n"), ("smooth", "false"), ("sensitivity", "true")]),
            );
            assert_eq!(s, Settings { level : 8, smooth : false, sensitivity : true });
            assert_eq!(Settings::read(stored(& [("level", "99")])).level, 10);
            let round: Vec<(&str, String)> = s.stored().into();
            let back: Vec<(&str, &str)> = round
                .iter()
                .map(|(k, v)| (*k, v.as_str()))
                .collect();
            assert_eq!(Settings::read(stored(& back)), s);
        }
        #[test]
        fn buttons_cycle_as_the_extra_did() {
            let mut s = Settings {
                level: 10,
                smooth: true,
                sensitivity: false,
            };
            s.click(0);
            assert_eq!(s.level, 2);
            s.level = 5;
            s.click(0);
            assert_eq!(s.level, 3);
            s.click(1);
            s.click(2);
            assert_eq!(
                s.labels(), ["Starting zoom: 3x", "Smooth zoom: OFF",
                "Slower turning: ON"]
            );
        }
        #[test]
        fn holds_zooms_with_the_wheel_and_lets_go() {
            let none = stored(&[]);
            key(false, true, &none);
            assert_eq!(view(), None, "not while a screen is open");
            assert!(! wheel(1.0));
            key(true, true, &none);
            assert_eq!(view(), Some((4.0, true, 0.25)));
            assert!(wheel(1.0));
            assert_eq!(view().map(| v | v.0), Some(5.0));
            assert!(wheel(40.0));
            assert_eq!(view().map(| v | v.0), Some(10.0));
            key(false, false, &none);
            assert_eq!(view(), None);
            assert!(! wheel(1.0));
        }
    }
}
